"use client";

import { useTheme } from "next-themes";
import { useRouter } from "next/navigation";
import { useState, useRef, useEffect } from "react";
import Image from "next/image";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";

import {
  ArrowRight,
  Bot,
  Shield,
  Zap,
  Code,
  Globe,
  Sparkles,
  User,
  Sun,
  Moon,
  Send,
} from "lucide-react";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
}

export default function HomePage() {
  const router = useRouter();
  const { theme, setTheme } = useTheme();

  const [messages, setMessages] = useState<Message[]>([
    {
      id: "1",
      role: "assistant",
      content:
        "Hello! I'm Nova, your AI product analyst. What product would you like to analyze today?",
    },
  ]);

  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = () => {
    if (!input.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: "user",
      content: input,
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setIsLoading(true);

    setTimeout(() => {
      setMessages((prev) => [
        ...prev,
        {
          id: `${Date.now()}-ai`,
          role: "assistant",
          content:
            "Based on your metrics, improving mobile UX will reduce churn significantly.",
        },
      ]);
      setIsLoading(false);
    }, 1000);
  };

  return (
    <div className="min-h-screen bg-background text-foreground overflow-x-hidden">
      {/* Background */}
      <div className="fixed inset-0 z-0 opacity-20 pointer-events-none">
        <Image
          src="../assets/abstract_dark_ai_technology_background_with_glowing_lines.png"
          alt="Background"
          fill
          className="object-cover"
          priority
        />
      </div>

      {/* Navbar */}
      <nav className="fixed top-0 w-full z-50 backdrop-blur border-b">
        <div className="container mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Bot className="h-6 w-6" />
            <span className="font-bold">Nova</span>
          </div>

          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
            >
              {theme === "dark" ? <Sun /> : <Moon />}
            </Button>

            <Button onClick={() => router.push("/chat")}>
              Get Started
            </Button>
          </div>
        </div>
      </nav>

      {/* Hero */}
      <section className="relative z-10 pt-32 container mx-auto px-4 grid lg:grid-cols-2 gap-12">
        <div>
          <Badge className="mb-6">
            <Sparkles className="w-4 h-4 mr-2" />
            Powered by GPT-5
          </Badge>

          <h1 className="text-6xl font-bold mb-6">
            Analyze Products with AI
          </h1>

          <p className="text-muted-foreground mb-8">
            Instant insights into pricing, churn, and feature gaps.
          </p>

          <Button size="lg" onClick={() => router.push("/chat")}>
            Start Analysis
            <ArrowRight className="ml-2 h-4 w-4" />
          </Button>
        </div>

        {/* Demo Chat */}
        <div className="bg-muted/30 rounded-xl shadow-xl overflow-hidden">
          <ScrollArea className="h-[420px] p-4">
            <div className="space-y-4">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${
                    msg.role === "user" ? "justify-end" : "justify-start"
                  }`}
                >
                  {msg.role === "assistant" && (
                    <Avatar className="h-6 w-6 mr-2">
                      <AvatarFallback>N</AvatarFallback>
                    </Avatar>
                  )}

                  <div
                    className={`px-3 py-2 rounded-lg max-w-xs text-sm ${
                      msg.role === "user"
                        ? "bg-primary text-white"
                        : "bg-muted"
                    }`}
                  >
                    {msg.content}
                  </div>
                </div>
              ))}
              <div ref={scrollRef} />
            </div>
          </ScrollArea>

          <div className="p-4 border-t flex gap-2">
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSendMessage()}
              placeholder="Ask about your product..."
              className="flex-1 rounded-full px-4 py-2 border"
            />
            <Button size="icon" onClick={handleSendMessage}>
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
}
